13	const THEATRE_QUERY_KEY = "theatre";
14	const THEATRE_QUERY_ENABLED = "1";
15	
16	const THEATRE_BRIDGE_FACTORIES: Readonly<
17	  Partial<Record<string, TheatreBridgeFactory>>
18	> = {
19	  [pageAbout]: async (engine, controls, hooks) => {
20	    const { AboutTheatreBridge } =
21	      await import("../pages/about/theatre/AboutTheatreBridge.js");
22	    return AboutTheatreBridge.create(engine, controls, hooks);
23	  },
24	  [pageMain]: async (engine, controls, hooks) => {
25	    const { MainTheatreBridge } =
26	      await import("../pages/main/theatre/MainTheatreBridge.js");
27	    return MainTheatreBridge.create(engine, controls, hooks);
28	  },
29	  [pageContact]: async (engine, controls, hooks) => {
30	    const { ContactTheatreBridge } =
31	      await import("../pages/contact/theatre/ContactTheatreBridge.js");
32	    return ContactTheatreBridge.create(engine, controls, hooks);
33	  },
34	};
