93	
94	  private _bindItem(item: HTMLElement): void {
95	    if (item.dataset[WHY_SKILL_PREVIEW.boundFlag] === "true") return;
96	    const binding: WhySkillBinding = {
97	      item,
98	      onEnter: () => this._onEnter(item),
99	      onLeave: () => this._scheduleHide(),
100	    };
101	    item.dataset[WHY_SKILL_PREVIEW.boundFlag] = "true";
102	    item.addEventListener("mouseenter", binding.onEnter);
103	    item.addEventListener("mouseleave", binding.onLeave);
104	    this.bindings.push(binding);
105	  }
106	
107	  private _onEnter(item: HTMLElement): void {
108	    this._clearHideTimer();
109	    this.preview.classList.remove(WHY_SKILL_PREVIEW.closingClass);
110	
111	    const videoSrc = item.getAttribute(this.videoDataAttr);
112	    if (!videoSrc) return;
113	
114	    const isSameItem = this.currentItem === item;
115	    if (isSameItem) return;
116	
117	    if (this.getVisibleState()) {
118	      // 이미 다른 스킬이 열려있음 — cinematic switch
119	      if (this.isSwitching) {
120	        this.pendingItem = item;
121	        this.pendingSrc = videoSrc;
122	        return;
123	      }
124	      this._startSwitch(item, videoSrc);
125	    } else {
126	      this._pauseVideo();
127	      this.video.src = videoSrc;
128	      this.video.load();
129	      this.currentItem = item;
130	      this._updatePosition(item);
131	      this._show();
132	      this.video.play().catch(() => {/* autoplay policy — silent */});
133	    }
134	  }
135	
136	  private _updatePosition(item: HTMLElement): void {
137	    const rect = item.getBoundingClientRect();
138	    const centerY = rect.top + rect.height / 2;
139	    this.preview.style.top = `${centerY}px`;
140	  }
141	
142	  private _startSwitch(item: HTMLElement, videoSrc: string): void {
143	    this.isSwitching = true;
144	    this.preview.classList.add(WHY_SKILL_PREVIEW.switchingClass);
145	
146	    this.switchTimer = window.setTimeout(() => {
147	      this._pauseVideo();
148	      this.video.src = videoSrc;
149	      this.video.load();
150	      this.currentItem = item;
151	      this._updatePosition(item);
152	
153	      this.preview.classList.remove(WHY_SKILL_PREVIEW.switchingClass);
154	      this.video.play().catch(() => {/* autoplay policy — silent */});
155	
156	      this.isSwitching = false;
157	      this.switchTimer = null;
158	
159	      if (this.pendingItem !== null && this.pendingSrc !== null) {
160	        const nextItem = this.pendingItem;
161	        const nextSrc = this.pendingSrc;
162	        this.pendingItem = null;
163	        this.pendingSrc = null;
164	        if (nextItem !== this.currentItem) {
165	          this._startSwitch(nextItem, nextSrc);
166	        }
167	      }
168	    }, WHY_SKILL_PREVIEW.switchAnimMs);
169	  }
170	
171	  private _scheduleHide(): void {
172	    this._clearHideTimer();
173	    this.hideTimer = window.setTimeout(() => {
174	      this._startClosing();
175	      window.setTimeout(() => {
176	        this.preview.classList.remove(WHY_SKILL_PREVIEW.closingClass);
177	      }, WHY_SKILL_PREVIEW.closeAnimationMs);
178	      this.currentItem = null;
179	      this.hideTimer = null;
180	    }, WHY_SKILL_PREVIEW.closeDelayMs);
181	  }
182	
183	  private _startClosing(): void {
184	    this._pauseVideo();
185	    this._hide();
186	    this.preview.classList.add(WHY_SKILL_PREVIEW.closingClass);
187	  }
188	
189	  private _show(): void {
190	    this.setVisibleOn();
191	  }
192	
193	  private _hide(): void {
194	    this.setVisibleOff();
195	  }
196	
197	  private _pauseVideo(): void {
198	    if (!this.video.paused) this.video.pause();
199	  }
200	
201	  private _clearHideTimer(): void {
202	    if (this.hideTimer === null) return;
203	    window.clearTimeout(this.hideTimer);
204	    this.hideTimer = null;
205	  }
206	
207	  private _clearSwitchTimer(): void {
208	    if (this.switchTimer === null) return;
209	    window.clearTimeout(this.switchTimer);
210	    this.switchTimer = null;
211	    this.isSwitching = false;
212	    this.pendingItem = null;
213	    this.pendingSrc = null;
214	  }
215	}
