16	  vyMult: number;
17	  vz: number;
18	  vzMult: number;
19	  bounced: boolean;
20	  gravity: number;
21	  startGravity: number;
22	  rotDir: number;
23	  sphere: THREE.Mesh;
24	  material: THREE.MeshLambertMaterial;
25	}
26	
27	type ResolvedOpts = {
28	  attachTo: string;
29	  spawnOffset: { x?: number; y?: number; z?: number };
30	  floorLevel: number;
31	  floorDimensions: number;
32	  radius: number;
33	  colors: string[];
34	  dotsPerInterval: number;
35	  physicsScale: number;
36	  textureUrl: string;
37	};
38	
39	// Scale-deincrement per tick matching original `radius(3) * -0.002 = -0.006`
40	// Ball lifetime: (1.0 - 0.1) / 0.006 = 150 ticks ≈ 2.25 s
41	const SHRINK_RATE = -0.006;
42	// Opacity fade starts at this scale and reaches 0 at the removal threshold (0.1)
43	const FADE_START_SCALE = 0.5;
44	// Smoke dissipation constants extracted from rotateSmoke() reference
45	const SMOKE_Z_DRIFT = 0.002;   // position.z drift per tick when fading
46	const SMOKE_SPREAD = 1.003;    // x/y spread multiplier per tick when fading
47	
48	const DEFAULTS = {
49	  attachTo: "rocket",
50	  spawnOffset: { x: 0 as number, y: -0.34 as number, z: 0 as number },
51	  floorLevel: -2.5,
52	  floorDimensions: 25,
53	  radius: 0.05,
54	  colors: ["#bada55", "#bada55", "#bada55", "#bada55"] as string[],
55	  dotsPerInterval: 5,
56	  physicsScale: 0.017,
57	  textureUrl: "",
58	};
59	
60	export class GravityBalls extends SceneObject<Record<string, never>> {
61	  private readonly _balls = new Map<number, SphereInfo>();
62	  private _idx = 0;
63	  private _accumMs = 0;
64	  private readonly _spawnPt = new THREE.Vector3();
65	  private _opts: GravityBallsObjectOptions = {};
66	  private _floorMesh: THREE.Mesh | null = null;
67	  private _geo: THREE.PlaneGeometry | null = null;
68	  private _texture: THREE.Texture | null = null;
69	  // Base material template — cloned per ball for independent opacity
70	  private _baseMat: THREE.MeshLambertMaterial | null = null;
71	
72	  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
73	    if (props) this._opts = { ...this._opts, ...props };
74	    return this;
75	  }
76	
77	  protected override getOptions(): Record<string, unknown> {
78	    return this._opts as Record<string, unknown>;
79	  }
80	
81	  override async runObject(): Promise<void> {
82	    const ctx = this._context;
83	    if (!ctx) return;
84	
85	    const o = this._resolve();
86	
87	    // Load smoke texture if configured
88	    if (o.textureUrl && ctx.loadTexture) {
89	      try {
90	        this._texture = await ctx.loadTexture(this.resolveAssetPath(o.textureUrl));
91	      } catch {
92	        // Texture load failed — fall back to flat color
93	      }
94	    }
95	
96	    // PlaneGeometry: each ball is a textured quad (diameter = radius * 2)
97	    this._geo = new THREE.PlaneGeometry(o.radius * 2, o.radius * 2);
98	
99	    this._baseMat = new THREE.MeshLambertMaterial({
100	      color: 0xffffff,
101	      emissive: 0x888888,
102	      map: this._texture ?? null,
103	      transparent: true,
104	      depthWrite: false,
105	      opacity: 0.8,
106	    });
107	
108	    const floorGeo = new THREE.BoxGeometry(o.floorDimensions, 0.05, o.floorDimensions);
109	    const floorMat = new THREE.MeshLambertMaterial({
110	      color: "#000000",
111	      depthWrite: false,
112	      transparent: true,
113	      opacity: 0.2,
114	    });
115	    this._floorMesh = new THREE.Mesh(floorGeo, floorMat);
116	    this._floorMesh.position.y = o.floorLevel - o.radius / 2;
117	    ctx.scene.add(this._floorMesh);
118	
119	    this._applyOptionVisibility();
120	  }
121	
122	  override runUpdate(delta: number): void {
123	    const ctx = this._context;
124	    if (!ctx || this._disposed) return;
125	
126	    this._accumMs += delta * 1000;
127	    if (this._accumMs >= 15) {
128	      this._accumMs -= 15;
129	      this._tick(ctx);
130	    }
131	
132	    const q = ctx.camera.quaternion;
133	    this._balls.forEach(b => { b.sphere.quaternion.copy(q); });
134	  }
135	
136	  private _tick(ctx: SceneObjectContext): void {
137	    const o = this._resolve();
138	
139	    if (o.attachTo) {
140	      const rkt = ctx.getObject(o.attachTo);
141	      if (rkt instanceof THREE.Object3D) {
142	        rkt.getWorldPosition(this._spawnPt);
143	        this._spawnPt.x += o.spawnOffset.x ?? 0;
144	        this._spawnPt.y += o.spawnOffset.y ?? 0;
145	        this._spawnPt.z += o.spawnOffset.z ?? 0;
146	      }
147	    }
148	
149	    for (let i = 0; i < o.dotsPerInterval; i++) this._spawn(ctx, o);
150	
151	    const dead: number[] = [];
152	    this._balls.forEach((b, id) => { if (this._step(b, o)) dead.push(id); });
153	    for (const id of dead) this._balls.delete(id);
154	  }
155	
156	  private _spawn(ctx: SceneObjectContext, o: ResolvedOpts): void {
157	    const geo = this._geo;
158	    const baseMat = this._baseMat;
159	    if (!geo || !baseMat) return;
160	
161	    const s = o.physicsScale;
162	    // Clone base material so each ball controls opacity independently
163	    const ballMat = baseMat.clone();
164	
165	    const isXNeg = this._rnd(1, 2) === 1;
166	    const isZNeg = this._rnd(1, 2) === 1;
167	    let sy = this._spawnPt.y;
168	    if (sy < o.floorLevel - o.radius / 2) sy = o.floorLevel - o.radius / 2;
169	
170	    const mesh = new THREE.Mesh(geo, ballMat);
171	    // Random initial rotation so smoke planes don't all look identical
172	    mesh.rotation.z = Math.random() * Math.PI * 2;
173	
174	    const info: SphereInfo = {
175	      ID: ++this._idx,
176	      color: o.colors[this._rnd(0, o.colors.length)] ?? o.colors[0],
177	      radiusStart: o.radius,
178	      startX: this._spawnPt.x,
179	      startY: sy,
180	      startZ: this._spawnPt.z,
181	      vx: isXNeg ? this._rnd(0, 50) * -0.15 * s : this._rnd(0, 50) * 0.15 * s,
182	      vxMult: this._rnd(10, 20) * 0.15,
183	      vy: this._rnd(-10, 20) * s,
184	      vyMult: this._rnd(4, 6) * -0.1,
185	      vz: isZNeg ? this._rnd(-25, 25) * -0.4 * s : this._rnd(-25, 25) * 0.4 * s,
186	      vzMult: this._rnd(10, 20) * 0.1,
187	      bounced: false,
188	      startGravity: 10 * s,
189	      gravity: 10 * s,
190	      // Random rotation speed ±0.003–0.009 rad/tick (≈ delta * 0.4 from reference)
191	      rotDir: (Math.random() < 0.5 ? 1 : -1) * (0.003 + Math.random() * 0.006),
192	      sphere: mesh,
193	      material: ballMat,
194	    };
195	
196	    ctx.scene.add(mesh);
197	    this._balls.set(info.ID, info);
198	  }
199	
200	  // Returns true when the ball should be removed
201	  private _step(b: SphereInfo, o: ResolvedOpts): boolean {
202	    const sp = b.sphere;
203	
204	    sp.scale.x += SHRINK_RATE;
205	    sp.scale.y += SHRINK_RATE;
206	    sp.scale.z += SHRINK_RATE;
207	
208	    b.startX += b.vx * 0.6;
209	    b.startY -= b.vy * 0.5;
210	    b.startZ -= b.vz * 0.6;
211	    sp.position.x = b.startX;
212	    sp.position.y = b.startY;
213	    sp.position.z = b.startZ;
214	
215	    if (sp.position.y < o.floorLevel - b.radiusStart / 2) {
216	      if (!b.bounced) {
217	        b.vx *= b.vxMult;
218	        b.vz *= b.vzMult;
219	      } else {
220	        b.vx *= 0.95;
221	        b.vz *= 0.95;
222	      }
223	
224	      const h = o.floorDimensions / 2;
225	      const outOfBounds =
226	        sp.position.x > h || sp.position.x < -h ||
227	        sp.position.z > h || sp.position.z < -h;
228	
229	      if (!outOfBounds) {
230	        b.vy *= b.vyMult;
231	        sp.position.y = o.floorLevel + b.radiusStart * sp.scale.x;
232	        b.startY = sp.position.y;
233	      } else {
234	        b.gravity = b.startGravity / 4;
235	        b.startY -= b.vy * 0.01;
236	        sp.position.y = b.startY + (20 * o.physicsScale - b.radiusStart * sp.scale.x);
237	      }
238	      b.bounced = true;
239	    }
240	
241	    b.vy += b.gravity;
242	
243	    // Always rotate slowly (smoke drift effect)
244	    sp.rotation.z += b.rotDir;
245	
246	    // Fade phase: opacity + smoke dissipation (z-drift + subtle x/y spread)
247	    if (sp.scale.y < FADE_START_SCALE) {
248	      b.material.opacity = Math.max(0, (sp.scale.y - 0.1) / (FADE_START_SCALE - 0.1));
249	      sp.position.z -= SMOKE_Z_DRIFT;
250	      b.startX *= SMOKE_SPREAD;
251	      b.startY *= SMOKE_SPREAD;
252	    }
253	
254	    if (sp.scale.y <= 0.1) {
255	      this._context?.scene.remove(sp);
256	      b.material.dispose();
257	      return true;
258	    }
259	    return false;
260	  }
261	
262	  protected override applyVisibility(visible: boolean): void {
263	    if (this._floorMesh) this._floorMesh.visible = visible;
264	    this._balls.forEach(b => { b.sphere.visible = visible; });
265	  }
266	
267	  override dispose(): void {
268	    if (this._disposed) return;
269	    const scene = this._context?.scene;
270	
271	    if (this._floorMesh) {
272	      scene?.remove(this._floorMesh);
273	      this._floorMesh.geometry.dispose();
274	      (this._floorMesh.material as THREE.Material).dispose();
275	      this._floorMesh = null;
276	    }
277	
278	    this._balls.forEach(b => {
279	      scene?.remove(b.sphere);
280	      b.material.dispose();
281	    });
282	    this._balls.clear();
283	
284	    this._geo?.dispose();
285	    this._geo = null;
286	    this._baseMat?.dispose();
287	    this._baseMat = null;
288	    // Texture is owned by the engine's texture cache via ctx.loadTexture — do not dispose
289	
290	    super.dispose();
291	  }
292	
293	  private _resolve(): ResolvedOpts {
294	    const o = this._opts;
295	    return {
296	      attachTo: o.attachTo ?? DEFAULTS.attachTo,
297	      spawnOffset: o.spawnOffset ?? DEFAULTS.spawnOffset,
298	      floorLevel: o.floorLevel ?? DEFAULTS.floorLevel,
299	      floorDimensions: o.floorDimensions ?? DEFAULTS.floorDimensions,
300	      radius: o.radius ?? DEFAULTS.radius,
301	      colors: (o.colors && o.colors.length > 0) ? o.colors : DEFAULTS.colors,
302	      dotsPerInterval: o.dotsPerInterval ?? DEFAULTS.dotsPerInterval,
303	      physicsScale: o.physicsScale ?? DEFAULTS.physicsScale,
304	      textureUrl: o.textureUrl ?? DEFAULTS.textureUrl,
305	    };
306	  }
307	
308	  // Original random(min, max) = Math.floor(Math.random() * max) + min
309	  private _rnd(min: number, max: number): number {
310	    return Math.floor(Math.random() * max) + min;
311	  }
312	}
